func SolvePuzzle() Solution {
	sol := solution{}
	if !search(sol, 0) {
		// The puzzle is guaranteed to have a unique solution; this cannot happen.
		panic("no solution found")
	}
	for h := 0; h < numHouses; h++ {
		if sol.drinks[h] == "water" {
			sol.DrinksWater = sol.nations[h]
		}
		if sol.pets[h] == "zebra" {
			sol.OwnsZebra = sol.nations[h]
		}
	}
	return sol
}
```

