	if house == numHouses {
		return true
	}
	for _, color := range colors {
		if s.colorUsed(color) {
			continue
		}
		if !colorAllowed(s, house, color) {
			continue
		}
		s.colors[house] = color
		for _, nation := range nations {
			if s.nationUsed(nation) {
				continue
			}
			if !nationAllowed(s, house, nation) {
				continue
			}
			s.nations[house] = nation
			for _, pet := range pets {
				if s.petUsed(pet) {
					continue
				}
				if !petAllowed(s, house, pet) {
					continue
				}
				s.pets[house] = pet
				for _, drink := range drinks {
					if s.drinkUsed(drink) {
						continue
					}
					if !drinkAllowed(s, house, drink) {
						continue
					}
					s.drinks[house] = drink
					for _, cig := range cigarettes {
						if s.cigUsed(cig) {
							continue
						}
						if !cigAllowed(s, house, cig) {
							continue
						}
						s.cigarettes[house] = cig
						if consistent(s, house) && search(s, house+1) {
							return true
						}
						// undo
						s.cigarettes[house] = ""
					}
					s.drinks[house] = ""
				}
				s.pets[house] = ""
			}
			s.nations[house] = ""
		}
		s.colors[house] = ""
	}
	return false
}
```

